#include <stdio.h>

/* teste do desafio de MODULO a-caixa-do-frete — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: o teste CHAMA as funcoes do aluno pelo prototipo e confere o
   valor DEVOLVIDO com checa_int. Nao ha captura de stdout aqui — o que a
   funcao imprimir nao e conferido, porque o que ela entrega e o valor. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int cabeNaSacola(int pesoGramas);
int oFreteDaEntrega(int pesoGramas, int distanciaKm);

SM_TEST(o_pacote_que_cabe) {
    /* o caminho comum: cabe na sacola, nada de manuseio */
    checa_int("o frete do pacote leve", oFreteDaEntrega(1000, 10), 650,
              "taxa fixa 500, mais 10 pedacos de 100 gramas a 3, mais 10 km a 12");
    checa_int("a sacola aceita 1000 gramas", cabeNaSacola(1000), 1,
              "mil gramas e menos que dois mil: a comparacao vale 1");
}

SM_TEST(o_pacote_que_nao_cabe) {
    /* o manuseio entra quando a sacola nao aceita */
    checa_int("o frete com manuseio", oFreteDaEntrega(2500, 10), 1495,
              "nao cabe na sacola, entao os 800 de manuseio entram na conta");
    checa_int("a sacola recusa 2500 gramas", cabeNaSacola(2500), 0,
              "dois mil e quinhentos passa do limite: a comparacao vale 0");
}

SM_TEST(o_pedido_impossivel) {
    /* devolver cedo: o pedido impossivel sai antes da conta */
    checa_int("peso zerado", oFreteDaEntrega(0, 5), -1,
              "peso 0 nao e entrega: devolve -1 antes de qualquer conta");
    checa_int("distancia zerada", oFreteDaEntrega(500, 0), -1,
              "distancia 0 nao e entrega: devolve -1 antes de qualquer conta");
    checa_int("peso negativo", oFreteDaEntrega(-200, 5), -1,
              "peso negativo tambem e pedido impossivel");
}

SM_TEST(o_teto_do_frete) {
    /* o teto corta o total quando a conta passa de 5000 */
    checa_int("o frete estourado vira o teto", oFreteDaEntrega(9000, 300), 5000,
              "a conta passaria de 5000, e o teto responde no lugar dela");
}

SM_TEST(as_bordas_da_sacola) {
    /* as duas bordas do limite da sacola, na mesma pesagem */
    checa_int("dois mil gramas AINDA cabe", cabeNaSacola(2000), 1,
              "o limite e ate 2000 inclusive: <= e nao <");
    checa_int("dois mil e um NAO cabe", cabeNaSacola(2001), 0,
              "um grama acima do limite ja sai da sacola");
    checa_int("o frete na borda nao tem manuseio", oFreteDaEntrega(2000, 1), 572,
              "cabendo na sacola, os 800 nao entram");
}

