#include <stdio.h>

int cabeNaSacola(int pesoGramas) {
    return pesoGramas <= 2000;
}

int oFreteDaEntrega(int pesoGramas, int distanciaKm) {
    if (pesoGramas <= 0) {
        return -1;
    }
    if (distanciaKm <= 0) {
        return -1;
    }

    int total = 500 + (pesoGramas / 100) * 3 + distanciaKm * 12;

    if (cabeNaSacola(pesoGramas) == 0) {
        total = total + 800;
    }

    if (total > 5000) {
        return 5000;
    }

    return total;
}
